import{_ as i,o as t,c as a,aj as e}from"./chunks/framework.C6uXqnaX.js";const k=JSON.parse('{"title":"Manage marked text with custom IDs","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/i18n/manage-marked-text.md","filePath":"en/guide/i18n/manage-marked-text.md"}'),n={name:"en/guide/i18n/manage-marked-text.md"};function l(h,s,o,p,d,r){return t(),a("div",null,s[0]||(s[0]=[e(`<h1 id="manage-marked-text-with-custom-ids" tabindex="-1">Manage marked text with custom IDs <a class="header-anchor" href="#manage-marked-text-with-custom-ids" aria-label="Permalink to &quot;Manage marked text with custom IDs&quot;">​</a></h1><p>The Angular extractor generates a file with a translation unit entry each of the following instances.</p><ul><li>Each <code>i18n</code> attribute in a component template</li><li>Each <a href="./api/localize/init/$localize" title="$localize | init - localize - API | Angular"><code>$localize</code></a> tagged message string in component code</li></ul><p>As described in <a href="./guide/i18n/prepare#h1-example" title="How meanings control text extraction and merges - Prepare components for translations | Angular">How meanings control text extraction and merges</a>, Angular assigns each translation unit a unique ID.</p><p>The following example displays translation units with unique IDs.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;trans-unit id=&quot;ba0cc104d3d69bf669f97b8d96a4c5d8d9559aa3&quot; datatype=&quot;html&quot;&gt;</span></span></code></pre></div><p>When you change the translatable text, the extractor generates a new ID for that translation unit. In most cases, changes in the source text also require a change to the translation. Therefore, using a new ID keeps the text change in sync with translations.</p><p>However, some translation systems require a specific form or syntax for the ID. To address the requirement, use a custom ID to mark text. Most developers don&#39;t need to use a custom ID. If you want to use a unique syntax to convey additional metadata, use a custom ID. Additional metadata may include the library, component, or area of the application in which the text appears.</p><p>To specify a custom ID in the <code>i18n</code> attribute or <a href="./api/localize/init/$localize" title="$localize | init - localize - API | Angular"><code>$localize</code></a> tagged message string, use the <code>@@</code> prefix. The following example defines the <code>introductionHeader</code> custom ID in a heading element.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i18n</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@@introductionHeader&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Hello i18n!&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>The following example defines the <code>introductionHeader</code> custom ID for a variable.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">variableText1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> $localize</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`:@@introductionHeader:Hello i18n!\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>When you specify a custom ID, the extractor generates a translation unit with the custom ID.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;trans-unit id=&quot;introductionHeader&quot; datatype=&quot;html&quot;&gt;</span></span></code></pre></div><p>If you change the text, the extractor does not change the ID. As a result, you don&#39;t have to take the extra step to update the translation. The drawback of using custom IDs is that if you change the text, your translation may be out-of-sync with the newly changed source text.</p><h2 id="use-a-custom-id-with-a-description" tabindex="-1">Use a custom ID with a description <a class="header-anchor" href="#use-a-custom-id-with-a-description" aria-label="Permalink to &quot;Use a custom ID with a description&quot;">​</a></h2><p>Use a custom ID in combination with a description and a meaning to further help the translator.</p><p>The following example includes a description, followed by the custom ID.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i18n</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;An introduction header for this sample@@introductionHeader&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Hello i18n!&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>The following example defines the <code>introductionHeader</code> custom ID and description for a variable.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">variableText2 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> $localize</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`:An introduction header for this sample@@introductionHeader:Hello i18n!\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The following example adds a meaning.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i18n</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;site header|An introduction header for this sample@@introductionHeader&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Hello i18n!&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>The following example defines the <code>introductionHeader</code> custom ID for a variable.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">variableText3 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> $localize</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`:site header|An introduction header for this sample@@introductionHeader:Hello i18n!\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h3 id="define-unique-custom-ids" tabindex="-1">Define unique custom IDs <a class="header-anchor" href="#define-unique-custom-ids" aria-label="Permalink to &quot;Define unique custom IDs&quot;">​</a></h3><p>Be sure to define custom IDs that are unique. If you use the same ID for two different text elements, the extraction tool extracts only the first one, and Angular uses the translation in place of both original text elements.</p><p>For example, in the following code snippet the same <code>myId</code> custom ID is defined for two different text elements.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h3</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i18n</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@@myId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Hello&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- ... --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i18n</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@@myId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Good bye&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>The following displays the translation in French.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;trans-unit id=&quot;myId&quot; datatype=&quot;html&quot;&gt;</span></span>
<span class="line"><span>  &lt;source&gt;Hello&lt;/source&gt;</span></span>
<span class="line"><span>  &lt;target state=&quot;new&quot;&gt;Bonjour&lt;/target&gt;</span></span>
<span class="line"><span>&lt;/trans-unit&gt;</span></span></code></pre></div><p>Both elements now use the same translation (<code>Bonjour</code>), because both were defined with the same custom ID.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Bonjour&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- ... --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Bonjour&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div>`,33)]))}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
